#!/usr/bin/env python3
import json
import sys
from collections import Counter
from pathlib import Path

def summarize(path: Path):
    severities = Counter()
    signatures = Counter()
    malformed = 0
    with path.open("r", encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                event = json.loads(line)
            except json.JSONDecodeError:
                malformed += 1
                continue
            if event.get("event_type") != "alert":
                continue
            alert = event.get("alert") or {}
            severities[str(alert.get("severity", "unknown"))] += 1
            signatures[str(alert.get("signature", "unknown"))] += 1
    return severities, signatures, malformed

if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("usage: eve_summary.py EVE_JSONL")
    sev, sig, bad = summarize(Path(sys.argv[1]))
    print("severity:", dict(sorted(sev.items())))
    print("signatures:", dict(sig.most_common()))
    print("malformed:", bad)

from collections import defaultdict
from datetime import datetime, timedelta

def ts(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00"))

def detect(events, threshold=10, window_seconds=60):
    groups = defaultdict(list)
    for e in events:
        groups[(e["src_ip"], e["dst_ip"])].append(e)
    findings = []
    for (src, dst), group in groups.items():
        group.sort(key=lambda e: ts(e["timestamp"]))
        for i, start in enumerate(group):
            ports = set()
            used = []
            start_ts = ts(start["timestamp"])
            for e in group[i:]:
                if ts(e["timestamp"]) - start_ts > timedelta(seconds=window_seconds):
                    break
                ports.add(e["dst_port"])
                used.append(e)
            if len(ports) >= threshold:
                findings.append({
                    "rule_id":"NET-SCAN-PORT-FANOUT-001",
                    "severity":"medium",
                    "heuristic":True,
                    "src_ip":src,
                    "dst_ip":dst,
                    "distinct_destination_ports":sorted(ports),
                    "event_count":len(used),
                    "first_seen":used[0]["timestamp"],
                    "last_seen":used[-1]["timestamp"]
                })
                break
    return findings

