from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterator

from .models import Event


class InputFormatError(ValueError):
    pass


def normalize_suricata_timestamp(value: str) -> str:
    text = value.strip()
    if text.endswith("Z"):
        dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
    else:
        dt = datetime.fromisoformat(text)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def normalize_zeek_timestamp(value: float | int | str) -> str:
    dt = datetime.fromtimestamp(float(value), tz=timezone.utc)
    return dt.isoformat().replace("+00:00", "Z")


def _to_optional_int(value: Any) -> int | None:
    if value is None or value == "":
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def parse_suricata_record(record: dict[str, Any]) -> Event | None:
    if record.get("event_type") != "alert":
        return None

    alert = record.get("alert") or {}
    return Event(
        source="suricata",
        timestamp=normalize_suricata_timestamp(str(record["timestamp"])),
        event_type="alert",
        src_ip=record.get("src_ip"),
        src_port=_to_optional_int(record.get("src_port")),
        dst_ip=record.get("dest_ip"),
        dst_port=_to_optional_int(record.get("dest_port")),
        proto=record.get("proto"),
        severity=str(alert["severity"]) if "severity" in alert else None,
        signature=alert.get("signature"),
        raw=record,
    )


def parse_zeek_conn_record(record: dict[str, Any]) -> Event:
    required = ("ts", "id.orig_h", "id.resp_h", "proto")
    missing = [key for key in required if key not in record]
    if missing:
        raise InputFormatError(f"Zeek conn record missing required fields: {missing}")

    return Event(
        source="zeek",
        timestamp=normalize_zeek_timestamp(record["ts"]),
        event_type="conn",
        src_ip=record.get("id.orig_h"),
        src_port=_to_optional_int(record.get("id.orig_p")),
        dst_ip=record.get("id.resp_h"),
        dst_port=_to_optional_int(record.get("id.resp_p")),
        proto=str(record.get("proto")).lower() if record.get("proto") is not None else None,
        raw=record,
    )


def iter_jsonl(path: Path, max_line_bytes: int = 1_000_000) -> Iterator[dict[str, Any]]:
    with path.open("r", encoding="utf-8") as handle:
        for line_number, raw_line in enumerate(handle, start=1):
            if len(raw_line.encode("utf-8")) > max_line_bytes:
                raise InputFormatError(
                    f"{path}:{line_number}: line exceeds {max_line_bytes} bytes"
                )
            line = raw_line.strip()
            if not line:
                continue
            try:
                value = json.loads(line)
            except json.JSONDecodeError as exc:
                raise InputFormatError(
                    f"{path}:{line_number}: invalid JSON: {exc.msg}"
                ) from exc
            if not isinstance(value, dict):
                raise InputFormatError(
                    f"{path}:{line_number}: JSON value must be an object"
                )
            yield value


def read_suricata(path: Path) -> Iterator[Event]:
    for record in iter_jsonl(path):
        event = parse_suricata_record(record)
        if event is not None:
            yield event


def read_zeek_conn(path: Path) -> Iterator[Event]:
    for record in iter_jsonl(path):
        yield parse_zeek_conn_record(record)

