from __future__ import annotations

from collections import defaultdict
from datetime import timedelta
from typing import Any

from .models import Event
from .normalize import parse_event_time, sort_events


def detect_port_fanout(
    events: list[Event],
    threshold: int = 10,
    window_seconds: int = 60,
) -> list[dict[str, Any]]:
    if threshold < 1:
        raise ValueError("threshold must be >= 1")
    if window_seconds < 1:
        raise ValueError("window_seconds must be >= 1")

    grouped: dict[tuple[str | None, str | None], list[Event]] = defaultdict(list)
    for event in events:
        if event.src_ip and event.dst_ip and event.dst_port is not None:
            grouped[(event.src_ip, event.dst_ip)].append(event)

    findings: list[dict[str, Any]] = []
    window = timedelta(seconds=window_seconds)

    for (src_ip, dst_ip), group in grouped.items():
        ordered = sort_events(group)
        for start_index, start in enumerate(ordered):
            start_time = parse_event_time(start)
            ports: set[int] = set()
            evidence: list[Event] = []

            for candidate in ordered[start_index:]:
                if parse_event_time(candidate) - start_time > window:
                    break
                if candidate.dst_port is not None:
                    ports.add(candidate.dst_port)
                evidence.append(candidate)

            if len(ports) >= threshold:
                findings.append(
                    {
                        "rule_id": "NET-SCAN-PORT-FANOUT-001",
                        "severity": "medium",
                        "heuristic": True,
                        "src_ip": src_ip,
                        "dst_ip": dst_ip,
                        "distinct_destination_ports": sorted(ports),
                        "event_count": len(evidence),
                        "first_seen": evidence[0].timestamp,
                        "last_seen": evidence[-1].timestamp,
                        "reason": (
                            f"{len(ports)} distinct destination ports observed "
                            f"within {window_seconds} seconds"
                        ),
                    }
                )
                break

    return findings


def correlate_suricata_and_zeek(
    suricata_events: list[Event],
    zeek_events: list[Event],
    window_seconds: int = 30,
) -> list[dict[str, Any]]:
    if window_seconds < 0:
        raise ValueError("window_seconds must be >= 0")

    ordered_zeek = sort_events(zeek_events)
    correlations: list[dict[str, Any]] = []

    for alert in sort_events(suricata_events):
        candidates = []
        alert_time = parse_event_time(alert)
        for flow in ordered_zeek:
            if flow.src_ip != alert.src_ip or flow.dst_ip != alert.dst_ip:
                continue
            if alert.dst_port is not None and flow.dst_port != alert.dst_port:
                continue
            delta = abs((parse_event_time(flow) - alert_time).total_seconds())
            if delta <= window_seconds:
                candidates.append(
                    {
                        "zeek_timestamp": flow.timestamp,
                        "zeek_src_port": flow.src_port,
                        "zeek_dst_port": flow.dst_port,
                        "delta_seconds": round(delta, 6),
                    }
                )

        correlations.append(
            {
                "alert_timestamp": alert.timestamp,
                "signature": alert.signature,
                "src_ip": alert.src_ip,
                "dst_ip": alert.dst_ip,
                "matches": candidates,
            }
        )

    return correlations
